// Same secret scheme as SB-01 (ASSUMPTIONS A-03). Unknown statuses are flagged, not guessed (A-02).
const headerName = ($env.SENDBLUE_WEBHOOK_SECRET_HEADER || 'sb-signing-secret').toLowerCase();
const expected = $env.SENDBLUE_WEBHOOK_SECRET || '';
const headers = $json.headers || {};
const got = headers[headerName] || '';
let ok = expected.length > 0 && got.length === expected.length;
if (ok) { let d = 0; for (let i = 0; i < expected.length; i++) d |= expected.charCodeAt(i) ^ got.charCodeAt(i); ok = d === 0; }
const body = $json.body || {};
const KNOWN = ['REGISTERED','PENDING','SENT','DELIVERED','RECEIVED','QUEUED','ERROR','DECLINED','ACCEPTED','SUCCESS'];
const status = String(body.status || '').toUpperCase();
return [{ json: { secret_valid: ok, message_handle: body.message_handle || null, status, known_status: KNOWN.includes(status), error_code: body.error_code ?? null, error_message: body.error_message ? String(body.error_message).slice(0, 200) : null, is_outbound: body.is_outbound === true || String(body.is_outbound) === 'true' } }];

// Decide whether this status merits an ops alert (grouped, not per-event spam).
const j = $('Verify Secret + Normalize').first().json;
let alert = null;
if (!j.known_status && j.status) alert = { kind: 'unknown_status', detail: `Unrecognized Sendblue status "${j.status}" — verify against current docs (ASSUMPTIONS A-02)` };
else if (j.status === 'ERROR' || j.status === 'DECLINED') {
  const code = String(j.error_code || '');
  if (code === '401' || /auth/i.test(j.error_message || '')) alert = { kind: 'auth_error', detail: 'Sendblue reports authentication error on send — check API keys' };
  else if (code === '429' || /rate/i.test(j.error_message || '')) alert = { kind: 'rate_limit', detail: 'Sendblue rate limiting detected' };
  else if (/line|number/i.test(j.error_message || '')) alert = { kind: 'line_failure', detail: 'Possible line failure on the dedicated number' };
  else alert = { kind: 'delivery_failure', detail: `Delivery ${j.status} (code ${code || 'n/a'})` };
}
if (!alert) return [];
console.log(JSON.stringify({ level: 'warn', workflow: 'SB-07', workflow_version: '1.0.0', action: 'delivery_alert', kind: alert.kind, message_handle: j.message_handle, ts: new Date().toISOString() }));
return [{ json: { ...alert, message_handle: j.message_handle, status: j.status } }];
